    /**
     * Method to retrieve the Procedure via ProcedureFetchOneSummary
     * @param 	summary ProcedureFetchOneSummary 
     * @return 	ProcedureFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Procedure getProcedure( ProcedureFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ProcedureFetchOneSummary arg cannot be null" );
    	
    	Procedure entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Procedure
        	// --------------------------------------
        	CompletableFuture<Procedure> futureEntity = queryGateway.query(new FindProcedureQuery( new LoadProcedureFilter( summary.getProcedureId() ) ), ResponseTypes.instanceOf(Procedure.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Procedure with id " + summary.getProcedureId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


    /**
     * Method to retrieve a collection of all Procedures
     *
     * @return 	List<Procedure> 
     * @exception ProcessingException Thrown if any problems
     */
    public List<Procedure> getAllProcedure() 
    throws ProcessingException {
        List<Procedure> list = null;

        try {
        	CompletableFuture<List<Procedure>> futureList = queryGateway.query(new FindAllProcedureQuery(), ResponseTypes.multipleInstancesOf(Procedure.class));
        	
        	list = futureList.get();
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all Procedure";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }

    /**
     * assign Policy on Procedure
     * @param		command AssignPolicyToProcedureCommand	
     * @exception	ProcessingException
     */     
	public void assignPolicy( AssignPolicyToProcedureCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getProcedureId() );
		
		PolicyService childDelegate 	= PolicyService.getPolicyInstance();
		ProcedureService parentDelegate = ProcedureService.getProcedureInstance();			
		UUID childId = command.getAssignment().getPolicyId();
		Policy child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Policy using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

